[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>GlobalStone — Global Commercial Real Estate Services</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --navy: #0A1628;
      --navy-light: #1a2a4a;
      --teal: #0d7377;
      --teal-dark: #0A5C5F;
      --gold: #C9A961;
      --gold-light: #D4B978;
      --white: #FFFFFF;
      --gray-50: #F8FAFC;
      --gray-100: #F1F5F9;
      --gray-200: #E2E8F0;
      --gray-300: #CBD5E1;
      --gray-400: #94A3B8;
      --gray-500: #64748B;
      --gray-600: #475569;
      --gray-700: #334155;
      --gray-800: #1E293B;
      --gray-900: #0F172A;
      --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      --font-heading: 'Playfair Display', Georgia, serif;
      --transition: 250ms ease;
    }

    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font-body);
      color: var(--gray-800);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }

    /* Utility */
    .container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
    .visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); border: 0; }

    /* Header */
    .header {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      background: var(--navy);
      transition: var(--transition);
    }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 80px; padding: 0 32px;
    }
    .logo {
      display: flex; align-items: center; gap: 12px;
      color: var(--white); font-family: var(--font-heading); font-size: 1.5rem; font-weight: 600;
    }
    .logo-icon { width: 40px; height: 40px; background: var(--teal); border-radius: 4px; display: flex; align-items: center; justify-content: center; }
    .logo-icon svg { width: 24px; height: 24px; fill: var(--white); }

    .nav-desktop { display: flex; align-items: center; gap: 8px; }
    .nav-link {
      color: rgba(255,255,255,0.85); font-size: 0.9rem; font-weight: 500;
      padding: 8px 16px; border-radius: 6px; transition: var(--transition);
      position: relative;
    }
    .nav-link:hover { color: var(--white); background: rgba(255,255,255,0.08); }
    .nav-link.services-trigger { display: flex; align-items: center; gap: 6px; }
    .nav-link.services-trigger svg { width: 16px; height: 16px; transition: transform 200ms ease; }
    .nav-link.services-trigger:hover svg, .nav-link.services-trigger.active svg { transform: rotate(180deg); }

    .btn-primary {
      background: var(--teal); color: var(--white);
      padding: 10px 24px; border-radius: 6px; font-weight: 600; font-size: 0.9rem;
      transition: var(--transition);
    }
    .btn-primary:hover { background: var(--teal-dark); transform: translateY(-1px); }

    /* Mega Menu */
    .mega-menu {
      position: fixed; top: 80px; left: 0; right: 0;
      background: var(--white); border-top: 1px solid var(--gray-200);
      box-shadow: 0 20px 60px rgba(0,0,0,0.15);
      opacity: 0; visibility: hidden; transform: translateY(-10px);
      transition: opacity 200ms ease, transform 200ms ease, visibility 200ms;
      z-index: 999;
    }
    .mega-menu.active { opacity: 1; visibility: visible; transform: translateY(0); }
    .mega-menu-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; padding: 48px 32px; max-width: 1280px; margin: 0 auto; }
    .mega-menu-section h3 { font-size: 0.75rem; font-weight: 600; color: var(--gray-500); text-transform: uppercase; letter-spacing: 0.1em; margin-bottom: 20px; }
    .mega-menu-items { display: flex; flex-direction: column; gap: 12px; }
    .mega-menu-item {
      display: flex; align-items: flex-start; gap: 12px;
      padding: 12px 16px; border-radius: 8px; transition: var(--transition);
    }
    .mega-menu-item:hover { background: var(--gray-50); }
    .mega-menu-item-icon { width: 36px; height: 36px; background: var(--navy); border-radius: 6px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .mega-menu-item-icon svg { width: 18px; height: 18px; stroke: var(--white); fill: none; stroke-width: 2; }
    .mega-menu-item-content h4 { font-size: 0.95rem; font-weight: 600; color: var(--navy); margin-bottom: 2px; }
    .mega-menu-item-content p { font-size: 0.8rem; color: var(--gray-500); line-height: 1.4; }

    /* Mobile Nav */
    .nav-mobile-toggle { display: none; color: var(--white); padding: 8px; }
    .nav-mobile-toggle svg { width: 28px; height: 28px; }

    .mobile-nav {
      position: fixed; top: 80px; left: 0; right: 0; bottom: 0;
      background: var(--navy); z-index: 998;
      padding: 24px; overflow-y: auto;
      transform: translateX(100%); transition: transform 300ms ease;
    }
    .mobile-nav.active { transform: translateX(0); }
    .mobile-nav-item {
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }
    .mobile-nav-link {
      display: flex; align-items: center; justify-content: space-between;
      color: var(--white); font-size: 1.1rem; font-weight: 500;
      padding: 20px 0;
    }
    .mobile-nav-link svg { width: 20px; height: 20px; transition: transform 200ms; }
    .mobile-nav-link.active svg { transform: rotate(180deg); }
    .mobile-nav-sub {
      max-height: 0; overflow: hidden; transition: max-height 300ms ease;
      background: rgba(255,255,255,0.05);
    }
    .mobile-nav-sub.active { max-height: 500px; }
    .mobile-nav-sub a {
      display: block; color: rgba(255,255,255,0.7); font-size: 0.95rem;
      padding: 12px 16px;
    }
    .mobile-nav-sub a:hover { color: var(--white); }

    /* Hero */
    .hero {
      min-height: 100vh; padding-top: 80px;
      background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
      display: flex; align-items: center;
      position: relative; overflow: hidden;
    }
    .hero::before {
      content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect fill="none" stroke="rgba(255,255,255,0.03)" stroke-width="0.5" x="0" y="0" width="100" height="100"/></svg>');
      background-size: 60px 60px;
    }
    .hero-content {
      position: relative; z-index: 1;
      max-width: 720px;
    }
    .hero-eyebrow {
      display: inline-flex; align-items: center; gap: 8px;
      color: var(--gold); font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em;
      margin-bottom: 24px;
    }
    .hero-eyebrow::before { content: ''; width: 32px; height: 2px; background: var(--gold); }
    .hero h1 {
      font-family: var(--font-heading); font-size: clamp(2.5rem, 5vw, 4rem);
      color: var(--white); font-weight: 600; line-height: 1.15; margin-bottom: 24px;
    }
    .hero p { font-size: 1.2rem; color: rgba(255,255,255,0.8); line-height: 1.7; margin-bottom: 40px; }
    .hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .btn-hero-primary {
      background: var(--teal); color: var(--white); padding: 16px 32px;
      border-radius: 8px; font-weight: 600; font-size: 1rem;
      transition: var(--transition); display: inline-flex; align-items: center; gap: 8px;
    }
    .btn-hero-primary:hover { background: var(--teal-dark); }
    .btn-hero-secondary {
      background: transparent; color: var(--white); padding: 16px 32px;
      border: 2px solid rgba(255,255,255,0.3); border-radius: 8px;
      font-weight: 600; font-size: 1rem; transition: var(--transition);
    }
    .btn-hero-secondary:hover { border-color: var(--white); background: rgba(255,255,255,0.1); }

    /* Announcement Banner */
    .announcement {
      background: var(--teal); padding: 16px 0;
    }
    .announcement-inner {
      display: flex; align-items: center; justify-content: center; gap: 24px; flex-wrap: wrap;
      text-align: center;
    }
    .announcement p { color: var(--white); font-size: 0.95rem; font-weight: 500; }
    .announcement a {
      color: var(--gold); font-weight: 600; text-decoration: underline;
      text-underline-offset: 3px;
    }

    /* Featured Insights */
    .section { padding: 80px 0; }
    .section-dark { background: var(--gray-900); }
    .section-light { background: var(--gray-50); }
    .section-header { text-align: center; max-width: 640px; margin: 0 auto 48px; }
    .section-eyebrow { font-size: 0.8rem; font-weight: 600; color: var(--teal); text-transform: uppercase; letter-spacing: 0.1em; margin-bottom: 12px; }
    .section-title { font-family: var(--font-heading); font-size: clamp(1.75rem, 3vw, 2.5rem); color: var(--navy); font-weight: 600; margin-bottom: 16px; }
    .section-dark .section-title { color: var(--white); }
    .section-subtitle { color: var(--gray-600); font-size: 1.05rem; }
    .section-dark .section-subtitle { color: rgba(255,255,255,0.7); }

    .insights-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 24px; }
    .insight-card {
      background: var(--white); border-radius: 12px; overflow: hidden;
      box-shadow: 0 4px 20px rgba(0,0,0,0.06); transition: var(--transition);
    }
    .insight-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.12); }
    .insight-card-img { height: 180px; background: var(--navy); position: relative; overflow: hidden; }
    .insight-card-img::after {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(135deg, rgba(10,22,40,0.7) 0%, rgba(10,22,40,0.3) 100%);
    }
    .insight-card-badge {
      position: absolute; top: 16px; left: 16px; z-index: 1;
      background: var(--gold); color: var(--navy); font-size: 0.7rem; font-weight: 700;
      padding: 6px 12px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.05em;
    }
    .insight-card-body { padding: 24px; }
    .insight-card-meta { font-size: 0.8rem; color: var(--gray-500); margin-bottom: 8px; }
    .insight-card-title { font-size: 1.1rem; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 12px; }
    .insight-card-link { color: var(--teal); font-weight: 600; font-size: 0.9rem; display: inline-flex; align-items: center; gap: 6px; }
    .insight-card-link svg { width: 16px; height: 16px; transition: transform 200ms; }
    .insight-card:hover .insight-card-link svg { transform: translateX(4px); }

    /* About Statement */
    .about-statement { background: var(--navy); padding: 100px 0; }
    .about-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 80px; align-items: center; }
    .about-content { max-width: 520px; }
    .about-content .section-eyebrow { color: var(--gold); }
    .about-content h2 { font-family: var(--font-heading); font-size: clamp(1.75rem, 3vw, 2.5rem); color: var(--white); font-weight: 600; line-height: 1.3; margin-bottom: 24px; }
    .about-content p { color: rgba(255,255,255,0.8); font-size: 1.05rem; line-height: 1.8; margin-bottom: 32px; }
    .btn-outline { color: var(--white); border: 2px solid var(--gold); padding: 14px 28px; border-radius: 8px; font-weight: 600; display: inline-flex; align-items: center; gap: 8px; transition: var(--transition); }
    .btn-outline:hover { background: var(--gold); color: var(--navy); }
    .about-image { height: 400px; border-radius: 12px; overflow: hidden; position: relative; }
    .about-image img { width: 100%; height: 100%; object-fit: cover; }
    .about-image::after {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(135deg, rgba(10,22,40,0.3) 0%, transparent 50%);
    }

    /* What We Do Tabs */
    .what-we-do { padding: 100px 0; background: var(--white); }
    .tabs-container { display: grid; grid-template-columns: 280px 1fr; gap: 48px; margin-top: 48px; }
    .tabs-nav { display: flex; flex-direction: column; gap: 4px; }
    .tab-btn {
      text-align: left; padding: 20px 24px; border-radius: 8px;
      font-size: 1rem; font-weight: 600; color: var(--gray-600);
      transition: var(--transition); position: relative;
      border: 2px solid transparent;
    }
    .tab-btn:hover { color: var(--navy); background: var(--gray-50); }
    .tab-btn.active { color: var(--teal); background: var(--gray-50); border-color: var(--teal); }
    .tab-btn.active::before { content: ''; position: absolute; left: -2px; top: 50%; transform: translateY(-50%); width: 4px; height: 40px; background: var(--teal); border-radius: 0 4px 4px 0; }

    .tab-content { display: none; }
    .tab-content.active { display: block; }
    .tab-panel h3 { font-family: var(--font-heading); font-size: 1.75rem; color: var(--navy); font-weight: 600; margin-bottom: 16px; }
    .tab-panel p { color: var(--gray-600); font-size: 1.05rem; line-height: 1.8; margin-bottom: 32px; max-width: 600px; }
    .tab-panel .btn-primary { display: inline-flex; align-items: center; gap: 8px; }
    .tab-panel .btn-primary svg { width: 18px; height: 18px; }

    /* Newsletter */
    .newsletter { background: var(--teal-dark); padding: 80px 0; }
    .newsletter-inner { display: flex; align-items: center; justify-content: space-between; gap: 48px; flex-wrap: wrap; }
    .newsletter-content { flex: 1; min-width: 300px; }
    .newsletter-content h2 { font-family: var(--font-heading); font-size: 1.75rem; color: var(--white); font-weight: 600; margin-bottom: 8px; }
    .newsletter-content p { color: rgba(255,255,255,0.8); font-size: 1rem; }
    .newsletter-form { display: flex; gap: 12px; flex: 1; min-width: 300px; max-width: 500px; }
    .newsletter-form input {
      flex: 1; padding: 14px 20px; border: none; border-radius: 8px; font-size: 1rem;
      background: var(--white); color: var(--gray-800);
    }
    .newsletter-form input::placeholder { color: var(--gray-500); }
    .newsletter-form button {
      background: var(--gold); color: var(--navy); padding: 14px 28px; border-radius: 8px;
      font-weight: 600; font-size: 1rem; transition: var(--transition); white-space: nowrap;
    }
    .newsletter-form button:hover { background: var(--gold-light); }

    /* Latest Insights */
    .latest-insights { padding: 80px 0; }
    .latest-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; margin-bottom: 48px; }
    .latest-card { display: flex; gap: 20px; padding: 24px; background: var(--white); border-radius: 12px; border: 1px solid var(--gray-200); transition: var(--transition); }
    .latest-card:hover { border-color: var(--teal); box-shadow: 0 8px 30px rgba(0,0,0,0.08); }
    .latest-card-img { width: 120px; height: 100px; border-radius: 8px; background: var(--navy); flex-shrink: 0; overflow: hidden; }
    .latest-card-img img { width: 100%; height: 100%; object-fit: cover; }
    .latest-card-content { flex: 1; }
    .latest-card-tag { display: inline-block; background: var(--gray-100); color: var(--gray-600); font-size: 0.7rem; font-weight: 600; padding: 4px 10px; border-radius: 4px; text-transform: uppercase; margin-bottom: 8px; }
    .latest-card-title { font-size: 1rem; font-weight: 600; color: var(--navy); line-height: 1.4; margin-bottom: 8px; }
    .latest-card-date { font-size: 0.8rem; color: var(--gray-500); }
    .text-center { text-align: center; }

    /* Our Commitment */
    .commitment { padding: 100px 0; background: var(--gray-50); }
    .commitment-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 48px; }
    .commitment-card { background: var(--white); padding: 32px; border-radius: 12px; transition: var(--transition); }
    .commitment-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.1); }
    .commitment-icon { width: 56px; height: 56px; background: var(--navy); border-radius: 10px; display: flex; align-items: center; justify-content: center; margin-bottom: 20px; }
    .commitment-icon svg { width: 28px; height: 28px; stroke: var(--gold); fill: none; stroke-width: 1.5; }
    .commitment-card h3 { font-size: 1.1rem; font-weight: 600; color: var(--navy); margin-bottom: 12px; }
    .commitment-card p { font-size: 0.9rem; color: var(--gray-600); line-height: 1.6; margin-bottom: 20px; }
    .commitment-link { color: var(--teal); font-weight: 600; font-size: 0.9rem; display: inline-flex; align-items: center; gap: 6px; }
    .commitment-link svg { width: 16px; height: 16px; transition: transform 200ms; }
    .commitment-card:hover .commitment-link svg { transform: translateX(4px); }

    /* Footer */
    .footer { background: var(--navy); padding: 60px 0 30px; }
    .footer-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 48px; flex-wrap: wrap; margin-bottom: 48px; padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,0.1); }
    .footer-brand { max-width: 300px; }
    .footer-brand .logo { margin-bottom: 16px; }
    .footer-brand p { color: rgba(255,255,255,0.6); font-size: 0.9rem; line-height: 1.6; }
    .footer-links { display: flex; gap: 60px; flex-wrap: wrap; }
    .footer-col h4 { color: var(--white); font-size: 0.85rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em; margin-bottom: 20px; }
    .footer-col a { display: block; color: rgba(255,255,255,0.6); font-size: 0.9rem; padding: 6px 0; transition: var(--transition); }
    .footer-col a:hover { color: var(--white); }
    .footer-bottom { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 16px; }
    .footer-bottom p { color: rgba(255,255,255,0.5); font-size: 0.85rem; }
    .footer-legal { display: flex; gap: 24px; }
    .footer-legal a { color: rgba(255,255,255,0.5); font-size: 0.85rem; transition: var(--transition); }
    .footer-legal a:hover { color: var(--white); }

    /* Responsive */
    @media (max-width: 1024px) {
      .mega-menu-inner { grid-template-columns: 1fr; gap: 32px; }
      .about-inner { grid-template-columns: 1fr; gap: 48px; }
      .about-image { height: 300px; }
      .tabs-container { grid-template-columns: 1fr; }
      .tabs-nav { flex-direction: row; overflow-x: auto; padding-bottom: 8px; }
      .tab-btn { white-space: nowrap; }
      .tab-btn.active::before { display: none; }
      .commitment-grid { grid-template-columns: repeat(2, 1fr); }
      .latest-grid { grid-template-columns: 1fr; }
    }

    @media (max-width: 768px) {
      .nav-desktop { display: none; }
      .nav-mobile-toggle { display: block; }
      .hero h1 { font-size: 2.25rem; }
      .hero p { font-size: 1rem; }
      .newsletter-inner { flex-direction: column; text-align: center; }
      .newsletter-form { flex-direction: column; width: 100%; }
      .commitment-grid { grid-template-columns: 1fr; }
      .footer-top { flex-direction: column; }
      .footer-links { flex-direction: column; gap: 32px; }
      .footer-bottom { flex-direction: column; text-align: center; }
      .footer-legal { justify-content: center; }
      .section { padding: 60px 0; }
    }
  </style>
</head>
<body>
  <!-- Header -->
  <header class="header">
    <div class="header-inner">
      <a href="index.html" class="logo">
        <div class="logo-icon">
          <svg viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg>
        </div>
        GlobalStone
      </a>
      <nav class="nav-desktop">
        <button class="nav-link services-trigger" id="servicesTrigger" aria-expanded="false" aria-haspopup="true">
          Services
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 9l6 6 6-6"/></svg>
        </button>
        <a href="#" class="nav-link">Insights & Research</a>
        <a href="#" class="nav-link">Properties</a>
