        <a href="#" class="nav-link">About Us</a>
        <a href="#" class="btn-primary">Contact Us</a>
      </nav>
      <button class="nav-mobile-toggle" id="mobileToggle" aria-label="Toggle navigation">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 12h18M3 6h18M3 18h18"/></svg>
      </button>
    </div>

    <!-- Mega Menu -->
    <div class="mega-menu" id="megaMenu" role="region" aria-label="Services menu">
      <div class="mega-menu-inner">
        <div class="mega-menu-section">
          <h3>By Need</h3>
          <div class="mega-menu-items">
            <a href="services-invest-finance-value.html" class="mega-menu-item">
              <div class="mega-menu-item-icon">
                <svg viewBox="0 0 24 24"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
              </div>
              <div class="mega-menu-item-content">
                <h4>Invest, Finance & Value</h4>
                <p>Capital markets, valuation, and investment advisory</p>
              </div>
            </a>
            <a href="services-plan-lease-occupy.html" class="mega-menu-item">
              <div class="mega-menu-item-icon">
                <svg viewBox="0 0 24 24"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>
              </div>
              <div class="mega-menu-item-content">
                <h4>Plan, Lease & Occupy</h4>
                <p>Transaction services, site selection, and workplace solutions</p>
