  <script>
    // Mega Menu
    const servicesTrigger = document.getElementById('servicesTrigger');
    const megaMenu = document.getElementById('megaMenu');

    servicesTrigger.addEventListener('mouseenter', () => {
      megaMenu.classList.add('active');
      servicesTrigger.classList.add('active');
      servicesTrigger.setAttribute('aria-expanded', 'true');
    });

    megaMenu.addEventListener('mouseleave', () => {
      megaMenu.classList.remove('active');
      servicesTrigger.classList.remove('active');
      servicesTrigger.setAttribute('aria-expanded', 'false');
    });

    // Mobile Navigation
    const mobileToggle = document.getElementById('mobileToggle');
    const mobileNav = document.getElementById('mobileNav');

    mobileToggle.addEventListener('click', () => {
      mobileNav.classList.toggle('active');
      const isOpen = mobileNav.classList.contains('active');
      mobileToggle.setAttribute('aria-expanded', isOpen);
    });

    document.querySelectorAll('.mobile-nav-link').forEach(link => {
      if (link.nextElementSibling && link.nextElementSibling.classList.contains('mobile-nav-sub')) {
        link.addEventListener('click', (e) => {
          e.preventDefault();
          link.classList.toggle('active');
          link.setAttribute('aria-expanded', link.classList.contains('active'));
          link.nextElementSibling.classList.toggle('active');
        });
      }
    });
  </script>
</body>
